"""Collect HAProxy statistics and forward them to Graphite."""

import asyncio
import csv
import pickle
import re
import struct
import time
import urllib.request
from dataclasses import dataclass
from typing import Iterable, Iterator, Literal


@dataclass(frozen=True)
class GraphiteEvent:
    path: str
    value: float
    timestamp: int

    def serialize(self) -> tuple[str, tuple[int, float]]:
        return self.path, (self.timestamp, self.value)


@dataclass(frozen=True)
class HaproxyCapture:
    pxname: str
    svname: str
    field: list[str]

    def matches(self, row: dict) -> bool:
        """Return whether a HAProxy CSV row matches this capture."""
        return bool(
            re.match(self.pxname, row.get("pxname", ""))
            and re.match(self.svname, row.get("svname", ""))
            and all(name in row for name in self.field)
        )

    def to_graphite_events(
        self, prefix: str, row: dict, ts: float
    ) -> Iterator[GraphiteEvent]:
        """Convert selected numeric fields from a matching row into events."""
        if not self.matches(row):
            return

        for name in self.field:
            try:
                value = float(row[name])
            except (TypeError, ValueError):
                # HAProxy uses '-' for counters that do not apply to a row.
                continue
            path = f"{prefix}.{row['pxname']}.{row['svname']}.{name}"
            yield GraphiteEvent(path, value, int(ts))


TO_CAPTURE = [
    HaproxyCapture(".*", ".*", ["scur", "rate", "qcur"]),
]


def fetch_events(haproxy_url: str, prefix: str, ts: float) -> Iterable[GraphiteEvent]:
    """Fetch and parse HAProxy's CSV statistics page."""
    with urllib.request.urlopen(haproxy_url, timeout=10) as response:
        reader = csv.DictReader(response.read().decode("utf-8").splitlines())

    if reader.fieldnames:
        reader.fieldnames = [name.lstrip("# ") for name in reader.fieldnames]

    for raw_row in reader:
        row = {
            (key.lstrip("# ") if key else key): value
            for key, value in raw_row.items()
        }
        for capture in TO_CAPTURE:
            yield from capture.to_graphite_events(prefix, row, ts)


async def _send_events(events: list[GraphiteEvent], graphite_address: str) -> None:
    host, port = graphite_address.rsplit(":", 1)
    reader, writer = await asyncio.open_connection(host, int(port))
    del reader  # The pickle protocol only needs a one-way connection.
    payload = pickle.dumps([event.serialize() for event in events], protocol=2)
    writer.write(struct.pack("!L", len(payload)) + payload)
    await writer.drain()
    writer.close()
    await writer.wait_closed()


def _aggregate_events(
    events: list[GraphiteEvent], agg: Literal["max", "min", "sum"] | None
) -> list[GraphiteEvent]:
    if not agg:
        return events

    by_path: dict[str, list[GraphiteEvent]] = {}
    for event in events:
        by_path.setdefault(event.path, []).append(event)

    result = []
    for path, path_events in by_path.items():
        values = [event.value for event in path_events]
        value = {
            "max": max,
            "min": min,
            "sum": sum,
        }[agg](values)
        result.append(GraphiteEvent(path, value, path_events[-1].timestamp))
    return result


async def main(
    haproxy_url: str = "http://openlibrary.org/admin?stats",
    graphite_address: str = "graphite.us.archive.org:2004",
    prefix: str = "stats.ol.haproxy",
    dry_run: bool = True,
    fetch_freq: int = 10,
    commit_freq: int = 30,
    agg: Literal["max", "min", "sum"] | None = None,
) -> None:
    """Continuously collect HAProxy stats and print or send Graphite events."""
    buffered_events: list[GraphiteEvent] = []
    last_commit = time.monotonic()

    while True:
        started = time.monotonic()
        timestamp = time.time()
        events = await asyncio.to_thread(
            lambda: list(fetch_events(haproxy_url, prefix, timestamp))
        )
        buffered_events.extend(events)

        now = time.monotonic()
        if now - last_commit >= commit_freq:
            committed_events = _aggregate_events(buffered_events, agg)
            if dry_run:
                for event in committed_events:
                    print(f"{event.path} {event.value} {event.timestamp}", flush=True)
            elif committed_events:
                await _send_events(committed_events, graphite_address)
            buffered_events.clear()
            last_commit = now

        await asyncio.sleep(max(0, fetch_freq - (time.monotonic() - started)))
import os
import subprocess
import typing

from apscheduler.events import (
    EVENT_JOB_ERROR,
    EVENT_JOB_EXECUTED,
    EVENT_JOB_SUBMITTED,
    JobEvent,
)
from apscheduler.jobstores.base import JobLookupError
from apscheduler.schedulers.asyncio import AsyncIOScheduler
from apscheduler.schedulers.blocking import BlockingScheduler
from apscheduler.util import undefined


class _OlSchedulerDefaults:
    """Shared logging and job ID behavior for monitoring schedulers."""

    def __init__(self):
        super().__init__({'apscheduler.timezone': 'UTC'})
        self.add_listener(
            job_listener, EVENT_JOB_EXECUTED | EVENT_JOB_ERROR | EVENT_JOB_SUBMITTED
        )

    @typing.override
    def add_job(
        self,
        func,
        trigger=None,
        args=None,
        kwargs=None,
        id=None,
        name=None,
        misfire_grace_time=undefined,
        coalesce=undefined,
        max_instances=undefined,
        next_run_time=undefined,
        jobstore="default",
        executor="default",
        replace_existing=False,
        **trigger_args,
    ):
        return super().add_job(
            func,
            trigger,
            args,
            kwargs,
            # Override to avoid duplicating the function name everywhere
            id if id is not None else func.__name__,
            name,
            misfire_grace_time,
            coalesce,
            max_instances,
            next_run_time,
            jobstore,
            executor,
            replace_existing,
            **trigger_args,
        )


class OlBlockingScheduler(_OlSchedulerDefaults, BlockingScheduler):
    """Blocking scheduler retained for scripts that still use it."""


class OlAsyncIOScheduler(_OlSchedulerDefaults, AsyncIOScheduler):
    """Asyncio scheduler with UTC defaults and monitoring job listeners."""


def job_listener(event: JobEvent):
    if event.code == EVENT_JOB_SUBMITTED:
        print(f"[OL-MONITOR] Job {event.job_id} has started.", flush=True)
    elif event.code == EVENT_JOB_EXECUTED:
        print(f"[OL-MONITOR] Job {event.job_id} completed successfully.", flush=True)
    elif event.code == EVENT_JOB_ERROR:
        print(f"[OL-MONITOR] Job {event.job_id} failed.", flush=True)


def bash_run(cmd: str, sources: list[str] | None = None, capture_output=False):
    if not sources:
        sources = []

    source_paths = [
        (
            os.path.join("scripts", "monitoring", source)
            if not os.path.isabs(source)
            else source
        )
        for source in sources
    ]
    bash_command = "\n".join(
        (
            'set -e',
            *(f'source "{path}"' for path in source_paths),
            cmd,
        )
    )

    return subprocess.run(
        [
            "bash",
            "-c",
            bash_command,
        ],
        check=True,
        # Mainly for testing:
        capture_output=capture_output,
        text=capture_output if capture_output else None,
    )


def limit_server(allowed_hosts: list[str], scheduler):
    """
    Remove a scheduled job unless the environment hostname is in its allowlist.

    Patterns can be exact hostnames or prefix wildcards such as ``ol-web*``.
    Both the full hostname and its short name are checked.
    """

    def decorator(func):
        hostname = os.environ.get("HOSTNAME")
        names = {hostname, hostname.split(".", 1)[0]} if hostname else set()

        def matches(pattern: str) -> bool:
            if pattern.endswith("*"):
                prefix = pattern[:-1]
                return any(name.startswith(prefix) for name in names)
            return pattern in names

        if not any(matches(pattern) for pattern in allowed_hosts):
            # With the usual decorator order, scheduled_job has registered the
            # function immediately before this decorator runs.
            try:
                scheduler.remove_job(func.__name__)
            except JobLookupError:
                pass
        return func

    return decorator


def get_service_ip(image_name: str) -> str:
    """Return the first network IP for a Docker Compose service container."""
    container_name = image_name
    if not container_name.startswith("openlibrary-"):
        container_name = f"openlibrary-{container_name}-1"

    result = subprocess.run(
        [
            "docker",
            "inspect",
            "--format",
            "{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}",
            container_name,
        ],
        check=True,
        capture_output=True,
        text=True,
    )
    ip_address = result.stdout.strip()
    if not ip_address:
        raise RuntimeError(f"No network IP found for container {container_name!r}")
    return ip_address
